arguments.prompt:
You are implementing a Blazor Web App (Static SSR, no interactivity) for a university course catalog. The project is already scaffolded at `/tmp/sv-2286c4978a6949c9981126d10fc7446e/UniversityCourseCatalog`.

## Requirements
- Browse departments and courses in a searchable, filterable list
- View course detail pages (description, schedule, credits, instructor bio)
- Students submit an enrollment request form (name, student ID, course selection) — standard HTML form, no wizards or real-time validation
- Homepage shows featured courses and department links
- No authentication — open to all students and visitors
- Hosted on university intranet with fast, reliable connectivity

## Architecture Decisions
- Static SSR only (`-int None`) — no `@rendermode`, no `@onclick`, no JS interop
- Forms use HTML POST with `[SupplyParameterFromForm]` and `<AntiforgeryToken />`
- Navigation uses `[SupplyParameterFromQuery]` for search/filter parameters
- In-memory data service (no database) with sample data for departments, courses, instructors

## Tasks

### 1. Create Models (`Models/` folder)

Create `/tmp/sv-2286c4978a6949c9981126d10fc7446e/UniversityCourseCatalog/Models/` with:

**Department.cs**
```csharp
namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;  // e.g. "CS", "MATH"
    public string Description { get; set; } = string.Empty;
}
```

**Course.cs**
```csharp
namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;  // e.g. "CS 101"
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;  // e.g. "MWF 9:00-9:50 AM"
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}
```

**EnrollmentRequest.cs**
```csharp
using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., ST123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}
```

### 2. Create the Data Service

Create `/tmp/sv-2286c4978a6949c9981126d10fc7446e/UniversityCourseCatalog/Services/CatalogService.cs`:

```csharp
using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantities, and shapes." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their significance." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming. She holds a PhD from MIT and has published extensively on CS education.", IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design. Prerequisite: CS 101.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. Former ACM-ICPC world finalist.", IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 72 },
            new() { Id = 3, Title = "Operating Systems", Code = "CS 340", Description = "Concepts of operating system design including processes, memory management, file systems, and concurrency.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at Bell Labs before joining academia. Her research focuses on distributed systems and OS kernel design.", IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible. He has authored two bestselling textbooks.", IsFeatured = true, MaxEnrollment = 200, CurrentEnrollment = 180 },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel's research bridges pure mathematics and machine learning. She holds the Distinguished Teaching Award.", IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 67 },
            new() { Id = 6, Title = "Classical Mechanics", Code = "PHYS 201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and central force problems.", Credits = 4, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 3, DepartmentName = "Physics", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright combines theoretical physics with hands-on lab demonstrations. He previously worked at CERN.", IsFeatured = true, MaxEnrollment = 75, CurrentEnrollment = 60 },
            new() { Id = 7, Title = "Electromagnetism", Code = "PHYS 301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez is a former NASA researcher specializing in electromagnetic radiation and space physics.", IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 42 },
            new() { Id = 8, Title = "Creative Writing", Code = "ENG 210", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 4, DepartmentName = "English", InstructorName = "Prof. David Chang", InstructorBio = "Prof. Chang is a published novelist and poet. His work has appeared in The New Yorker and The Atlantic.", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 9, Title = "American Literature", Code = "ENG 320", Description = "Survey of American literature from the colonial period to the present. Covers major authors and movements.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", DepartmentId = 4, DepartmentName = "English", InstructorName = "Dr. Lisa Monroe", InstructorBio = "Dr. Monroe specializes in 20th-century American fiction and has published three books on modernist literature.", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new() { Id = 10, Title = "World History: 1500 to Present", Code = "HIST 102", Description = "Global perspectives on major historical events, movements, and transformations from 1500 to today.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 5, DepartmentName = "History", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a global historian focusing on cross-cultural exchanges. He has conducted research on four continents.", IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);
}
