            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible. He has authored two bestselling textbooks.", IsFeatured = true, MaxEnrollment = 200, CurrentEnrollment = 180 },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel's research bridges pure mathematics and machine learning. She holds the Distinguished Teaching Award.", IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 67 },
            new() { Id = 6, Title = "Classical Mechanics", Code = "PHYS 201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and central force problems.", Credits = 4, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 3, DepartmentName = "Physics", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright combines theoretical physics with hands-on lab demonstrations. He previously worked at CERN.", IsFeatured = true, MaxEnrollment = 75, CurrentEnrollment = 60 },
            new() { Id = 7, Title = "Electromagnetism", Code = "PHYS 301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez is a former NASA researcher specializing in electromagnetic radiation and space physics.", IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 42 },
            new() { Id = 8, Title = "Creative Writing", Code = "ENG 210", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 4, DepartmentName = "English", InstructorName = "Prof. David Chang", InstructorBio = "Prof. Chang is a published novelist and poet. His work has appeared in The New Yorker and The Atlantic.", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 9, Title = "American Literature", Code = "ENG 320", Description = "Survey of American literature from the colonial period to the present. Covers major authors and movements.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", DepartmentId = 4, DepartmentName = "English", InstructorName = "Dr. Lisa Monroe", InstructorBio = "Dr. Monroe specializes in 20th-century American fiction and has published three books on modernist literature.", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new() { Id = 10, Title = "World History: 1500 to Present", Code = "HIST 102", Description = "Global perspectives on major historical events, movements, and transformations from 1500 to today.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 5, DepartmentName = "History", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a global historian focusing on cross-cultural exchanges. He has conducted research on four continents.", IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);
}
